/**
 * A plausible French B2B draft, and a helper to vary it.
 *
 * One shared starting point keeps each test's `override` to the single field it is actually about,
 * so what a test is testing is visible in the call rather than buried in a wall of boilerplate.
 */

import type { DraftLine, InvoiceDraft } from '../../src/generate/draft.js';

