export function draftWith(override: Partial<InvoiceDraft>): InvoiceDraft {
  return { ...BASE_DRAFT, ...override };
}

export function lineWith(override: Partial<DraftLine>): DraftLine {
  return { ...BASE_DRAFT.lines[0]!, ...override };
}

